import os
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2.extras import RealDictCursor

app = Flask(__name__)

DB_DSN = os.environ.get('DATABASE_URL', 'postgresql://webapp:pass@localhost/appdb')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(DB_DSN, cursor_factory=RealDictCursor)
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def verify_token(token):
    """Verify user token and return user_id, role"""
    parts = token.split('.')
    if len(parts) != 3:
        return None
    payload, timestamp, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), f"{payload}.{timestamp}".encode(), hashlib.sha256).hexdigest()[:32]
    if not hmac.compare_digest(sig, expected):
        return None
    import json, base64
    data = json.loads(base64.b64decode(payload))
    return data

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report by executing a saved query template with user parameters"""
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    user = verify_token(auth[7:])
    if not user:
        return jsonify({'error': 'invalid token'}), 401

    body = request.get_json()
    template_id = body.get('template_id')
    params = body.get('params', {})

    db = get_db()
    cur = db.cursor()

    # Fetch the report template
    cur.execute("SELECT * FROM report_templates WHERE id = %s AND (org_id = %s OR is_public = true)",
                (template_id, user['org_id']))
    template = cur.fetchone()
    if not template:
        return jsonify({'error': 'template not found'}), 404

    # Template query uses named placeholders like {date_from}, {date_to}, {department}
    # We substitute user-provided params into the template query
    query = template['query_text']

    # Sanitize: only allow alphanumeric, spaces, dashes, and common chars in param values
    safe_params = {}
    for key, value in params.items():
        if not isinstance(value, str):
            value = str(value)
        # Strip dangerous characters - allow alphanumeric, space, dash, underscore, dot, colon
        cleaned = ''.join(c for c in value if c.isalnum() or c in ' -_.:/')
        safe_params[key] = cleaned

    try:
        # Build the final query from template + params
        final_query = query.format(**safe_params)
    except (KeyError, IndexError) as e:
        return jsonify({'error': f'missing parameter: {e}'}), 400

    # Execute with org_id restriction appended
    restricted_query = f"SELECT * FROM ({final_query}) AS report_data WHERE org_id = {user['org_id']}"

    try:
        cur.execute(restricted_query)
        results = cur.fetchall()
    except Exception as e:
        db.rollback()
        return jsonify({'error': 'query execution failed', 'detail': str(e)}), 500

    return jsonify({'data': results, 'count': len(results)})

@app.route('/api/reports/templates', methods=['GET'])
def list_templates():
    auth = request.headers.get('Authorization', '')
    if not auth.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401
    user = verify_token(auth[7:])
    if not user:
        return jsonify({'error': 'invalid token'}), 401

    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT id, name, description, param_schema FROM report_templates WHERE org_id = %s OR is_public = true",
                (user['org_id'],))
    return jsonify({'templates': cur.fetchall()})

